// Splitting and checking the SQL of a migration file (#163, ADR 0009).
//
// This is a validator, not a transpiler: it splits a file into statements at
// `;` outside quotes and comments, and reports what drizzle-cubrid will not
// apply. It never rewrites a statement. The rules are listed in
// docs/MIGRATIONS.md; most reject SQL written for MySQL (or generated by
// drizzle-kit for it), and the rest reject statements that would take the
// transaction away from the migrator or that the splitter cannot split.

/** One problem found in a migration file, with its 1-based position. */
export interface CubridMigrationIssue {
	/** The migration file name, when the SQL came from a file. */
	file?: string;
	line: number;
	column: number;
	message: string;
}

/** One statement of a migration file and the line it starts on. */
export interface CubridMigrationStatement {
	sql: string;
	line: number;
}

interface Token {
	kind: 'word' | 'quoted' | 'string' | 'symbol';
	/** Upper-cased for words, the character for symbols. */
	text: string;
	offset: number;
	line: number;
	column: number;
}

const TRANSACTION_CONTROL = new Set(['BEGIN', 'COMMIT', 'ROLLBACK', 'SAVEPOINT', 'START']);
const FOREIGN_STATEMENTS = new Set(['USE', 'DELIMITER', 'LOCK', 'UNLOCK']);
const FOREIGN_TYPE_MODIFIERS = new Set(['UNSIGNED', 'ZEROFILL']);

/**
 * Splits `text` into statements and checks them. `issues` is empty when the
 * file can be applied; the statements are returned either way.
 */
export function parseMigrationSql(
	text: string,
	file?: string,
): { statements: CubridMigrationStatement[]; issues: CubridMigrationIssue[] } {
	const issues: CubridMigrationIssue[] = [];
	const statements: CubridMigrationStatement[] = [];
	let tokens: Token[] = [];
	let i = 0;
	let line = 1;
	let column = 1;

	const issue = (atLine: number, atColumn: number, message: string) => {
		issues.push(
			file === undefined
				? { line: atLine, column: atColumn, message }
				: { file, line: atLine, column: atColumn, message },
		);
	};
	const advance = (count: number) => {
		for (let n = 0; n < count && i < text.length; n++, i++) {
			if (text[i] === '\n') {
				line++;
				column = 1;
			} else {
				column++;
			}
		}
	};
	const skipLine = () => {
		while (i < text.length && text[i] !== '\n') advance(1);
	};
	/** Consumes a quoted run that starts at `i`; `close` doubled is an escaped `close`. */
	const quoted = (close: string, what: string, doubled: boolean): boolean => {
		const startLine = line;
		const startColumn = column;
		advance(1);
		while (i < text.length) {
			if (text[i] === close) {
				if (doubled && text[i + 1] === close) {
					advance(2);
					continue;
				}
				advance(1);
				return true;
			}
			advance(1);
		}
		issue(startLine, startColumn, `Unterminated ${what}`);
		return false;
	};
	const endStatement = (end: number) => {
		if (tokens.length > 0) {
			const first = tokens[0]!;
			statements.push({ sql: text.slice(first.offset, end).trim(), line: first.line });
			checkStatement(tokens, issue);
		}
		tokens = [];
	};

	while (i < text.length) {
		const c = text[i]!;
		const next = text[i + 1];
		const start = { offset: i, line, column };
		if (c === '-' && next === '-') {
			if (text.startsWith('--> statement-breakpoint', i)) {
				issue(
					line,
					column,
					"'--> statement-breakpoint' is drizzle-kit's separator: drizzle-kit output is generated for another database, not CUBRID; write CUBRID SQL separated by ';'",
				);
			}
			skipLine();
		} else if (c === '/' && next === '/') {
			skipLine();
		} else if (c === '/' && next === '*') {
			if (text[i + 2] === '!') {
				issue(
					line,
					column,
					"A '/*! … */' conditional comment is MySQL syntax: MySQL runs its content, CUBRID ignores it as a comment",
				);
			}
			const close = text.indexOf('*/', i + 2);
			if (close < 0) {
				issue(line, column, 'Unterminated /* comment');
				advance(text.length - i);
			} else {
				advance(close + 2 - i);
			}
		} else if (c === '#') {
			issue(line, column, "A '#' comment is MySQL syntax, not CUBRID SQL; use '--'");
			skipLine();
		} else if (c === "'") {
			quoted("'", 'string literal', true);
			tokens.push({ kind: 'string', text: '', ...start });
		} else if (c === '"') {
			quoted('"', 'quoted identifier', true);
			tokens.push({ kind: 'quoted', text: '', ...start });
		} else if (c === '[') {
			quoted(']', 'bracketed identifier', false);
			tokens.push({ kind: 'quoted', text: '', ...start });
		} else if (c === '`') {
			const end = text.indexOf('`', i + 1);
			const name = end < 0 ? text.slice(i + 1, i + 31) : text.slice(i + 1, end);
			issue(
				line,
				column,
				`Backtick-quoted identifier \`${name}\`: backticks are how SQL generated for MySQL quotes names; quote identifiers with double quotes ("${name.replaceAll('"', '""')}")`,
			);
			quoted('`', 'backtick-quoted identifier', true);
			tokens.push({ kind: 'quoted', text: '', ...start });
		} else if (c === ';') {
			endStatement(i);
			advance(1);
		} else if (/\s/.test(c)) {
			advance(1);
		} else if (/[\p{L}\p{N}_]/u.test(c)) {
			let end = i + 1;
			while (end < text.length && /[\p{L}\p{N}_]/u.test(text[end]!)) end++;
			tokens.push({ kind: 'word', text: text.slice(i, end).toUpperCase(), ...start });
			advance(end - i);
		} else {
			if (c === '?') {
				issue(line, column, "A '?' parameter: migration statements take no bound values; write literals");
			}
			tokens.push({ kind: 'symbol', text: c, ...start });
			advance(1);
		}
	}
	endStatement(text.length);
	return { statements, issues };
}

function isWord(token: Token | undefined, ...words: string[]): boolean {
	return token?.kind === 'word' && words.includes(token.text);
}

/** The statement-level rules, on the tokens of one statement. */
function checkStatement(tokens: Token[], issue: (line: number, column: number, message: string) => void): void {
	const first = tokens[0]!;
	const at = (token: Token, message: string) => issue(token.line, token.column, message);
	if (isWord(first, ...TRANSACTION_CONTROL) || (isWord(first, 'SET') && isWord(tokens[1], 'TRANSACTION'))) {
		at(
			first,
			`${first.text} controls the transaction, which migrate() owns: each migration runs in one transaction that it commits or rolls back`,
		);
	} else if (isWord(first, ...FOREIGN_STATEMENTS)) {
		at(first, `${first.text} is a MySQL statement or client command, not CUBRID SQL`);
	} else if (isWord(first, 'CREATE')) {
		const kind = isWord(tokens[1], 'OR') && isWord(tokens[2], 'REPLACE') ? tokens[3] : tokens[1];
		if (isWord(kind, 'PROCEDURE', 'FUNCTION')) {
			at(
				first,
				`CREATE ${kind!.text} is not supported in migrations: its body contains ';', which the migration splitter cannot tell from a statement end; create stored routines outside migrate()`,
			);
		}
	}
	for (let n = 0; n < tokens.length; n++) {
		const token = tokens[n]!;
		const following = tokens[n + 1];
		if (token.kind !== 'word') continue;
		if (FOREIGN_TYPE_MODIFIERS.has(token.text)) {
			at(token, `${token.text} is a MySQL type modifier; CUBRID has no unsigned or zero-filled numeric types`);
		} else if (token.text === 'ENGINE' && following?.kind === 'symbol' && following.text === '=') {
			at(token, 'ENGINE= is a MySQL table option; CUBRID has no storage engines');
		} else if (token.text === 'DEFAULT' && isWord(following, 'CHARSET', 'CHARACTER')) {
			at(
				token,
				`DEFAULT ${following!.text} is a MySQL table option; CUBRID sets a table's character set with CHARSET <name> and COLLATE <name>`,
			);
		}
	}
}
